    fn error_as_ref<E>(error: &Self::Error<E>) -> Self::Error<&E>;
    /// Map a payload without widening an uninhabited state.
    fn map_error<E, F>(error: Self::Error<E>, map: impl FnOnce(E) -> F) -> Self::Error<F>;
    /// Fallible payload mapping, used by source range admission.
    /// # Errors
    /// Returns the mapping's error; impossible states never call it.
    fn try_map_error<E, F, X>(
        error: Self::Error<E>,
        map: impl FnOnce(E) -> Result<F, X>,
    ) -> Result<Self::Error<F>, X>;
