impl<'tree> FromNodeKind<'tree> for BaseContentItemChoice<'tree> {
    /** Classify a node into this choice's own alternatives.

    Returns `None` for a node of any other kind. That is a refusal,
    not a failure: the caller holds a node this choice does not
    describe, and saying so is the only true answer available.*/
    fn from_node(node: tree_sitter::Node<'tree>) -> Option<Self> {
        match (node.is_named(), node.kind()) {
            (true, "underline_begin") => Some(BaseContentItemChoice::UnderlineBegin(
                UnderlineBeginNode(node),
            )),
            (true, "underline_end") => {
                Some(BaseContentItemChoice::UnderlineEnd(UnderlineEndNode(node)))
            }
            (true, "pause_token") => Some(BaseContentItemChoice::PauseToken(PauseTokenNode(node))),
            (true, "word_with_optional_annotations") => {
                Some(BaseContentItemChoice::WordWithOptionalAnnotations(
                    WordWithOptionalAnnotationsNode(node),
                ))
            }
            (true, "nonword_with_optional_annotations") => {
                Some(BaseContentItemChoice::NonwordWithOptionalAnnotations(
                    NonwordWithOptionalAnnotationsNode(node),
                ))
            }
            (true, "other_spoken_event") => Some(BaseContentItemChoice::OtherSpokenEvent(
                OtherSpokenEventNode(node),
            )),
            (true, "long_feature") => {
                Some(BaseContentItemChoice::LongFeature(LongFeatureNode(node)))
            }
            (true, "nonvocal") => Some(BaseContentItemChoice::Nonvocal(NonvocalNode(node))),
            (true, "freecode") => Some(BaseContentItemChoice::Freecode(FreecodeNode(node))),
            (true, "bullet") => Some(BaseContentItemChoice::Bullet(BulletNode(node))),
            _ => None,
        }
    }
}
