impl<'tree> Extract<'tree> for ContentItemNode<'tree> {
    type Children<K: KindProof> = ContentItemChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<ContentItemChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children, &SHAPES_32);
            let content = {
                let __c0 = __cur.tail(&SHAPES_8);
                let (leading_extras, __placed) = __cur.fixed(
                    ChoiceAt {
                        shape: &SHAPE_108,
                        select: choice_108,
                        missing: &TAGS_3,
                    },
                    &__c0,
                );
                let slot = match __placed {
                    Some(__placed) => match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick108::A0(node) => {
                                ContentItemChoice::BaseContentItem(BaseContentItemNode(node))
                            }
                            ChoicePick108::A1(node) => ContentItemChoice::GroupWithAnnotations(
                                GroupWithAnnotationsNode(node),
                            ),
                            ChoicePick108::A2(node) => {
                                ContentItemChoice::QuotationWithOptionalAnnotations(
                                    QuotationWithOptionalAnnotationsNode(node),
                                )
                            }
                            ChoicePick108::A3(node) => {
                                ContentItemChoice::IllegalCurlyQuote(IllegalCurlyQuoteNode(node))
                            }
                            ChoicePick108::A4(node) => {
                                ContentItemChoice::MainPhoGroup(MainPhoGroupNode(node))
                            }
                            ChoicePick108::A5(node) => {
                                ContentItemChoice::MainSinGroup(MainSinGroupNode(node))
                            }
                            ChoicePick108::A6(node, tag) => {
                                ContentItemChoice::CaNoBreakLinker(match tag {
                                    KindTag2::CaNoBreakLinkerNode => {
                                        ContentItemCaNoBreakLinkerChoice::CaNoBreakLinker(
                                            CaNoBreakLinkerNode(node),
                                        )
                                    }
                                    KindTag2::CaTechnicalBreakLinkerNode => {
                                        ContentItemCaNoBreakLinkerChoice::CaTechnicalBreakLinker(
                                            CaTechnicalBreakLinkerNode(node),
                                        )
                                    }
                                    KindTag2::LinkerLazyOverlapNode => {
                                        ContentItemCaNoBreakLinkerChoice::LinkerLazyOverlap(
                                            LinkerLazyOverlapNode(node),
                                        )
                                    }
                                    KindTag2::LinkerQuickUptakeNode => {
                                        ContentItemCaNoBreakLinkerChoice::LinkerQuickUptake(
                                            LinkerQuickUptakeNode(node),
                                        )
                                    }
                                    KindTag2::LinkerQuickUptakeOverlapNode => {
                                        ContentItemCaNoBreakLinkerChoice::LinkerQuickUptakeOverlap(
                                            LinkerQuickUptakeOverlapNode(node),
                                        )
                                    }
                                    KindTag2::LinkerQuotationFollowsNode => {
                                        ContentItemCaNoBreakLinkerChoice::LinkerQuotationFollows(
                                            LinkerQuotationFollowsNode(node),
                                        )
                                    }
                                    KindTag2::LinkerSelfCompletionNode => {
                                        ContentItemCaNoBreakLinkerChoice::LinkerSelfCompletion(
                                            LinkerSelfCompletionNode(node),
                                        )
                                    }
                                })
                            }
                        }),
                        ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                            KindTag3::BaseContentItemNode => ContentItemMissing::BaseContentItem(
                                K::missing(KindMissing(BaseContentItemNode(node)))?,
                            ),
                            KindTag3::CaNoBreakLinkerNode => ContentItemMissing::CaNoBreakLinker(
                                KindMissing(CaNoBreakLinkerNode(node)),
                            ),
                            KindTag3::CaTechnicalBreakLinkerNode => {
                                ContentItemMissing::CaTechnicalBreakLinker(KindMissing(
                                    CaTechnicalBreakLinkerNode(node),
                                ))
                            }
                            KindTag3::GroupWithAnnotationsNode => {
                                ContentItemMissing::GroupWithAnnotations(K::missing(KindMissing(
                                    GroupWithAnnotationsNode(node),
                                ))?)
                            }
                            KindTag3::IllegalCurlyQuoteNode => {
                                ContentItemMissing::IllegalCurlyQuote(KindMissing(
                                    IllegalCurlyQuoteNode(node),
                                ))
                            }
                            KindTag3::LinkerLazyOverlapNode => {
                                ContentItemMissing::LinkerLazyOverlap(KindMissing(
                                    LinkerLazyOverlapNode(node),
                                ))
                            }
                            KindTag3::LinkerQuickUptakeNode => {
                                ContentItemMissing::LinkerQuickUptake(KindMissing(
                                    LinkerQuickUptakeNode(node),
                                ))
                            }
                            KindTag3::LinkerQuickUptakeOverlapNode => {
                                ContentItemMissing::LinkerQuickUptakeOverlap(KindMissing(
                                    LinkerQuickUptakeOverlapNode(node),
                                ))
                            }
                            KindTag3::LinkerQuotationFollowsNode => {
                                ContentItemMissing::LinkerQuotationFollows(KindMissing(
                                    LinkerQuotationFollowsNode(node),
                                ))
                            }
                            KindTag3::LinkerSelfCompletionNode => {
                                ContentItemMissing::LinkerSelfCompletion(KindMissing(
                                    LinkerSelfCompletionNode(node),
                                ))
                            }
                            KindTag3::MainPhoGroupNode => ContentItemMissing::MainPhoGroup(
                                K::missing(KindMissing(MainPhoGroupNode(node)))?,
                            ),
                            KindTag3::MainSinGroupNode => ContentItemMissing::MainSinGroup(
                                K::missing(KindMissing(MainSinGroupNode(node)))?,
                            ),
                            KindTag3::QuotationWithOptionalAnnotationsNode => {
                                ContentItemMissing::QuotationWithOptionalAnnotations(K::missing(
                                    KindMissing(QuotationWithOptionalAnnotationsNode(node)),
                                )?)
                            }
                        }),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                    None => NodeSlot::Absent(NoChild),
                };
                Positioned::new(leading_extras, slot)
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            ContentItemChildren {
                content,
                trailing_extras,
                unexpected,
            }
        })
    }
    fn extract_broad(self) -> ContentItemChildren<'tree> {
        extract_content_item(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<ContentItemChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
