/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_free_text<'tree>(node: FreeTextNode<'tree>) -> FreeTextChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_55);
    {
        let __f0 = {
            let __c0 = __cur.tail(&SHAPES_54);
            let (leading_extras, __placed) = __cur.fixed(
                ChoiceAt {
                    shape: &SHAPE_153,
                    select: choice_153,
                    missing: &TAGS_6,
                },
                &__c0,
            );
            let slot = match __placed {
                Some(__placed) => match __placed {
                    ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                        ChoicePick153::A0(node) => {
                            FreeTextChild0Choice::RestOfLine(RestOfLineNode(node))
                        }
                        ChoicePick153::A1(node) => {
                            FreeTextChild0Choice::Continuation(ContinuationNode(node))
                        }
                    }),
                    ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                        KindTag6::ContinuationNode => {
                            FreeTextChild0Missing::Continuation(KindMissing(ContinuationNode(node)))
                        }
                        KindTag6::RestOfLineNode => {
                            FreeTextChild0Missing::RestOfLine(KindMissing(RestOfLineNode(node)))
                        }
                    }),
                    ChoicePlaced::Error(node) => NodeSlot::Error(node),
                },
                None => NodeSlot::Absent(NoChild),
            };
            Positioned::new(leading_extras, slot)
        };
        let __f1 = {
            let __c1 = __cur.tail(&SHAPES_8);
            let (leading_extras, mut __walk) = __cur.repeat(&SHAPE_154, &__c1);
            let mut __items = Vec::with_capacity(__walk.capacity());
            while let Some((leading_extras, __placed, __c2)) = __walk.next(
                &mut __cur,
                ChoiceAt {
                    shape: &SHAPE_153,
                    select: choice_153,
                    missing: &TAGS_6,
                },
            ) {
                __items.push(Positioned::new(
                    leading_extras,
                    match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick153::A0(node) => {
                                FreeTextChild1Choice::RestOfLine(RestOfLineNode(node))
                            }
                            ChoicePick153::A1(node) => {
                                FreeTextChild1Choice::Continuation(ContinuationNode(node))
                            }
                        }),
                        ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                            KindTag6::ContinuationNode => FreeTextChild1Missing::Continuation(
                                KindMissing(ContinuationNode(node)),
                            ),
                            KindTag6::RestOfLineNode => {
                                FreeTextChild1Missing::RestOfLine(KindMissing(RestOfLineNode(node)))
                            }
                        }),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                ));
            }
            Positioned::new(leading_extras, __items)
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        FreeTextChildren {
            child_0: __f0,
            child_1: __f1,
            trailing_extras,
            unexpected,
        }
    }
}
