/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_id_language<'tree>(node: IdLanguageNode<'tree>) -> IdLanguageChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_85);
    let content = {
        let __c0 = __cur.tail(&SHAPES_8);
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_245,
                select: choice_245,
                missing: &TAGS_17,
            },
            &__c0,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick245::A0(node) => {
                        IdLanguageChoice::LanguageCode(LanguageCodeNode(node))
                    }
                    ChoicePick245::A1(node) => {
                        IdLanguageChoice::GenericIdLanguage(GenericIdLanguageNode(node))
                    }
                }),
                ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                    KindTag17::GenericIdLanguageNode => IdLanguageMissing::GenericIdLanguage(
                        KindMissing(GenericIdLanguageNode(node)),
                    ),
                    KindTag17::LanguageCodeNode => {
                        IdLanguageMissing::LanguageCode(KindMissing(LanguageCodeNode(node)))
                    }
                }),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    IdLanguageChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
