impl<'tree, 'source> SourceSlice<'tree, 'source> {
    /// Reconstruct an ERROR in this rule's position without losing
    /// source identity; a non-ERROR input returns `None`.
    #[must_use]
    pub fn extract_line_from_error_recovery(
        self,
    ) -> Option<SourceChildren<'tree, 'source, LineChildren<'tree>>> {
        into_ok(self.recover_as::<LineNode<'tree>, Broad>(LineNode, &()))
    }
    /// The same reconstruction under the admitted kind proof.
    /// # Errors
    /// The admitted proof's refusal; a non-ERROR input returns `Ok(None)`.
    pub fn extract_line_from_error_recovery_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<
        Option<SourceChildren<'tree, 'source, LineChildren<'tree, KindAdmitted>>>,
        AdmittedRefusal,
    > {
        self.recover_as::<LineNode<'tree>, KindAdmitted>(LineNode, grammar)
    }
}
/// `line`'s children from the ERROR standing in for one; see the module header.
#[must_use]
pub fn extract_line_from_error_recovery<'tree>(
    node: tree_sitter::Node<'tree>,
) -> Option<LineChildren<'tree>> {
    node.is_error().then(|| extract_line(LineNode(node)))
}

