impl<'tree> Extract<'tree> for LongFeatureNode<'tree> {
    type Children<K: KindProof> = LongFeatureChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<LongFeatureChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children, &SHAPES_107);
            let content = {
                let __c0 = __cur.tail(&SHAPES_8);
                let (leading_extras, __placed) = __cur.fixed(
                    ChoiceAt {
                        shape: &SHAPE_292,
                        select: choice_292,
                        missing: &TAGS_23,
                    },
                    &__c0,
                );
                let slot = match __placed {
                    Some(__placed) => match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick292::A0(node) => {
                                LongFeatureChoice::LongFeatureBegin(LongFeatureBeginNode(node))
                            }
                            ChoicePick292::A1(node) => {
                                LongFeatureChoice::LongFeatureEnd(LongFeatureEndNode(node))
                            }
                        }),
                        ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                            KindTag23::LongFeatureBeginNode => {
                                LongFeatureMissing::LongFeatureBegin(K::missing(KindMissing(
                                    LongFeatureBeginNode(node),
                                ))?)
                            }
                            KindTag23::LongFeatureEndNode => LongFeatureMissing::LongFeatureEnd(
                                K::missing(KindMissing(LongFeatureEndNode(node)))?,
                            ),
                        }),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                    None => NodeSlot::Absent(NoChild),
                };
                Positioned::new(leading_extras, slot)
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            LongFeatureChildren {
                content,
                trailing_extras,
                unexpected,
            }
        })
    }
    fn extract_broad(self) -> LongFeatureChildren<'tree> {
        extract_long_feature(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<LongFeatureChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
