/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_media_status<'tree>(node: MediaStatusNode<'tree>) -> MediaStatusChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_122);
    let content = {
        let __c0 = __cur.tail(&SHAPES_8);
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_336,
                select: choice_336,
                missing: &TAGS_24,
            },
            &__c0,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick336::A0(node) => {
                        MediaStatusChoice::MissingValue(MissingValueNode(node))
                    }
                    ChoicePick336::A1(node) => {
                        MediaStatusChoice::UnlinkedValue(UnlinkedValueNode(node))
                    }
                    ChoicePick336::A2(node) => {
                        MediaStatusChoice::NotransValue(NotransValueNode(node))
                    }
                    ChoicePick336::A3(node) => {
                        MediaStatusChoice::GenericMediaStatus(GenericMediaStatusNode(node))
                    }
                }),
                ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                    KindTag24::GenericMediaStatusNode => MediaStatusMissing::GenericMediaStatus(
                        KindMissing(GenericMediaStatusNode(node)),
                    ),
                    KindTag24::MissingValueNode => {
                        MediaStatusMissing::MissingValue(KindMissing(MissingValueNode(node)))
                    }
                    KindTag24::NotransValueNode => {
                        MediaStatusMissing::NotransValue(KindMissing(NotransValueNode(node)))
                    }
                    KindTag24::UnlinkedValueNode => {
                        MediaStatusMissing::UnlinkedValue(KindMissing(UnlinkedValueNode(node)))
                    }
                }),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    MediaStatusChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
