/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_media_type<'tree>(node: MediaTypeNode<'tree>) -> MediaTypeChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_124);
    let content = {
        let __c0 = __cur.tail(&SHAPES_8);
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_341,
                select: choice_341,
                missing: &TAGS_25,
            },
            &__c0,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick341::A0(node) => MediaTypeChoice::VideoValue(VideoValueNode(node)),
                    ChoicePick341::A1(node) => MediaTypeChoice::AudioValue(AudioValueNode(node)),
                    ChoicePick341::A2(node) => {
                        MediaTypeChoice::MissingValue(MissingValueNode(node))
                    }
                    ChoicePick341::A3(node) => {
                        MediaTypeChoice::GenericMediaType(GenericMediaTypeNode(node))
                    }
                }),
                ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                    KindTag25::AudioValueNode => {
                        MediaTypeMissing::AudioValue(KindMissing(AudioValueNode(node)))
                    }
                    KindTag25::GenericMediaTypeNode => {
                        MediaTypeMissing::GenericMediaType(KindMissing(GenericMediaTypeNode(node)))
                    }
                    KindTag25::MissingValueNode => {
                        MediaTypeMissing::MissingValue(KindMissing(MissingValueNode(node)))
                    }
                    KindTag25::VideoValueNode => {
                        MediaTypeMissing::VideoValue(KindMissing(VideoValueNode(node)))
                    }
                }),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    MediaTypeChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
