impl<'tree> Extract<'tree> for NonwordNode<'tree> {
    type Children<K: KindProof> = NonwordChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<NonwordChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children, &SHAPES_147);
            let content = {
                let __c0 = __cur.tail(&SHAPES_8);
                let (leading_extras, __placed) = __cur.fixed(
                    ChoiceAt {
                        shape: &SHAPE_414,
                        select: choice_414,
                        missing: &TAGS_29,
                    },
                    &__c0,
                );
                let slot = match __placed {
                    Some(__placed) => match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick414::A0(node) => NonwordChoice::Event(EventNode(node)),
                            ChoicePick414::A1(node) => NonwordChoice::Zero(ZeroNode(node)),
                        }),
                        ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                            KindTag29::EventNode => {
                                NonwordMissing::Event(K::missing(KindMissing(EventNode(node)))?)
                            }
                            KindTag29::ZeroNode => {
                                NonwordMissing::Zero(KindMissing(ZeroNode(node)))
                            }
                        }),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                    None => NodeSlot::Absent(NoChild),
                };
                Positioned::new(leading_extras, slot)
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            NonwordChildren {
                content,
                trailing_extras,
                unexpected,
            }
        })
    }
    fn extract_broad(self) -> NonwordChildren<'tree> {
        extract_nonword(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<NonwordChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
