/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_number_option<'tree>(node: NumberOptionNode<'tree>) -> NumberOptionChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_151);
    let content = {
        let __c0 = __cur.tail(&SHAPES_8);
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_431,
                select: choice_431,
                missing: &TAGS_30,
            },
            &__c0,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick431::A0(node) => NumberOptionChoice::_1(K1Node(node)),
                    ChoicePick431::A1(node) => NumberOptionChoice::_2(K2Node(node)),
                    ChoicePick431::A2(node) => NumberOptionChoice::_3(K3Node(node)),
                    ChoicePick431::A3(node) => NumberOptionChoice::_4(K4Node(node)),
                    ChoicePick431::A4(node) => NumberOptionChoice::_5(K5Node(node)),
                    ChoicePick431::A5(node) => NumberOptionChoice::More(MoreNode(node)),
                    ChoicePick431::A6(node) => NumberOptionChoice::Audience(AudienceNode(node)),
                    ChoicePick431::A7(node) => {
                        NumberOptionChoice::GenericNumber(GenericNumberNode(node))
                    }
                }),
                ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                    KindTag30::K1Node => NumberOptionMissing::K1(KindMissing(K1Node(node))),
                    KindTag30::K2Node => NumberOptionMissing::K2(KindMissing(K2Node(node))),
                    KindTag30::K3Node => NumberOptionMissing::K3(KindMissing(K3Node(node))),
                    KindTag30::K4Node => NumberOptionMissing::K4(KindMissing(K4Node(node))),
                    KindTag30::K5Node => NumberOptionMissing::K5(KindMissing(K5Node(node))),
                    KindTag30::AudienceNode => {
                        NumberOptionMissing::Audience(KindMissing(AudienceNode(node)))
                    }
                    KindTag30::GenericNumberNode => {
                        NumberOptionMissing::GenericNumber(KindMissing(GenericNumberNode(node)))
                    }
                    KindTag30::MoreNode => NumberOptionMissing::More(KindMissing(MoreNode(node))),
                }),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    NumberOptionChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
