/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_pho_group<'tree>(node: PhoGroupNode<'tree>) -> PhoGroupChildren<'tree> {
    into_ok(<PhoGroupNode<'tree> as Extract<'tree>>::extract_as::<Broad>(node, &()))
}
impl<'tree> Extract<'tree> for PhoGroupNode<'tree> {
    type Children<K: KindProof> = PhoGroupChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<PhoGroupChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children, &SHAPES_171);
            let content = {
                let __c0 = __cur.tail(&SHAPES_8);
                let (leading_extras, __placed) = __cur.fixed(
                    ChoiceAt {
                        shape: &SHAPE_481,
                        select: choice_481,
                        missing: &TAGS_32,
                    },
                    &__c0,
                );
                let slot = match __placed {
                    Some(__placed) => match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick481::A0(node) => PhoGroupChoice::PhoWords(PhoWordsNode(node)),
                            ChoicePick481::A1 => PhoGroupChoice::PhoBeginGroup({
                                let __f0 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_304), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(PhoBeginGroupNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                                KindMissing(PhoBeginGroupNode(node)),
                                            ),
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                let __f1 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_478), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(PhoGroupedContentNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => {
                                                NodeSlot::Missing(K::missing(KindMissing(
                                                    PhoGroupedContentNode(node),
                                                ))?)
                                            }
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                let __f2 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_302), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(PhoEndGroupNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                                KindMissing(PhoEndGroupNode(node)),
                                            ),
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                PhoGroupPhoBeginGroupChildren {
                                    child_0: __f0,
                                    child_1: __f1,
                                    child_2: __f2,
                                    trailing_extras: Vec::new(),
                                    unexpected: Vec::new(),
                                }
                            }),
                        }),
                        ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                            KindTag32::PhoWordsNode => PhoGroupMissing::PhoWords(K::missing(
                                KindMissing(PhoWordsNode(node)),
                            )?),
                        }),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                    None => NodeSlot::Absent(NoChild),
                };
                Positioned::new(leading_extras, slot)
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            PhoGroupChildren {
                content,
                trailing_extras,
                unexpected,
            }
        })
    }
    fn extract_broad(self) -> PhoGroupChildren<'tree> {
        extract_pho_group(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<PhoGroupChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
