/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_sin_group<'tree>(node: SinGroupNode<'tree>) -> SinGroupChildren<'tree> {
    into_ok(<SinGroupNode<'tree> as Extract<'tree>>::extract_as::<Broad>(node, &()))
}
impl<'tree> Extract<'tree> for SinGroupNode<'tree> {
    type Children<K: KindProof> = SinGroupChildren<'tree, K>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<SinGroupChildren<'tree, K>, K::Refusal> {
        let __raw = K::admit(evidence, self.0)?;
        Ok({
            let __children = collect_children(__raw);
            let mut __cur = Cursor::new(&__children, &SHAPES_199);
            let content = {
                let __c0 = __cur.tail(&SHAPES_8);
                let (leading_extras, __placed) = __cur.fixed(
                    ChoiceAt {
                        shape: &SHAPE_548,
                        select: choice_548,
                        missing: &TAGS_35,
                    },
                    &__c0,
                );
                let slot = match __placed {
                    Some(__placed) => match __placed {
                        ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                            ChoicePick548::A0(node) => SinGroupChoice::SinWord(SinWordNode(node)),
                            ChoicePick548::A1 => SinGroupChoice::SinBeginGroup({
                                let __f0 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_308), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(SinBeginGroupNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                                KindMissing(SinBeginGroupNode(node)),
                                            ),
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                let __f1 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_545), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(SinGroupedContentNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => {
                                                NodeSlot::Missing(K::missing(KindMissing(
                                                    SinGroupedContentNode(node),
                                                ))?)
                                            }
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                let __f2 = {
                                    let (leading_extras, __placed) =
                                        __cur.fixed(Terminal::of(&SHAPE_306), &Cont::NIL);
                                    let slot = match __placed {
                                        Some(__placed) => match __placed {
                                            TerminalPlaced::Present(node, ()) => {
                                                NodeSlot::Present(SinEndGroupNode(node))
                                            }
                                            TerminalPlaced::Missing(node, ()) => NodeSlot::Missing(
                                                KindMissing(SinEndGroupNode(node)),
                                            ),
                                            TerminalPlaced::Error(node) => NodeSlot::Error(node),
                                        },
                                        None => NodeSlot::Absent(NoChild),
                                    };
                                    Positioned::new(leading_extras, slot)
                                };
                                SinGroupSinBeginGroupChildren {
                                    child_0: __f0,
                                    child_1: __f1,
                                    child_2: __f2,
                                    trailing_extras: Vec::new(),
                                    unexpected: Vec::new(),
                                }
                            }),
                        }),
                        ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                            KindTag35::SinWordNode => SinGroupMissing::SinWord(K::missing(
                                KindMissing(SinWordNode(node)),
                            )?),
                        }),
                        ChoicePlaced::Error(node) => NodeSlot::Error(node),
                    },
                    None => NodeSlot::Absent(NoChild),
                };
                Positioned::new(leading_extras, slot)
            };
            let Leftovers {
                trailing_extras,
                unexpected,
            } = __cur.finish();
            SinGroupChildren {
                content,
                trailing_extras,
                unexpected,
            }
        })
    }
    fn extract_broad(self) -> SinGroupChildren<'tree> {
        extract_sin_group(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<SinGroupChildren<'tree, KindAdmitted>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
