impl<'tree> FromNodeKind<'tree> for TerminatorChoice<'tree> {
    /** Classify a node into this choice's own alternatives.

    Returns `None` for a node of any other kind. That is a refusal,
    not a failure: the caller holds a node this choice does not
    describe, and saying so is the only true answer available.*/
    fn from_node(node: tree_sitter::Node<'tree>) -> Option<Self> {
        match (node.is_named(), node.kind()) {
            (true, "break_for_coding") => {
                Some(TerminatorChoice::BreakForCoding(BreakForCodingNode(node)))
            }
            (true, "broken_question") => {
                Some(TerminatorChoice::BrokenQuestion(BrokenQuestionNode(node)))
            }
            (true, "exclamation") => Some(TerminatorChoice::Exclamation(ExclamationNode(node))),
            (true, "interrupted_question") => Some(TerminatorChoice::InterruptedQuestion(
                InterruptedQuestionNode(node),
            )),
            (true, "interruption") => Some(TerminatorChoice::Interruption(InterruptionNode(node))),
            (true, "period") => Some(TerminatorChoice::Period(PeriodNode(node))),
            (true, "question") => Some(TerminatorChoice::Question(QuestionNode(node))),
            (true, "quoted_new_line") => {
                Some(TerminatorChoice::QuotedNewLine(QuotedNewLineNode(node)))
            }
            (true, "quoted_period_simple") => Some(TerminatorChoice::QuotedPeriodSimple(
                QuotedPeriodSimpleNode(node),
            )),
            (true, "self_interrupted_question") => Some(TerminatorChoice::SelfInterruptedQuestion(
                SelfInterruptedQuestionNode(node),
            )),
            (true, "self_interruption") => Some(TerminatorChoice::SelfInterruption(
                SelfInterruptionNode(node),
            )),
            (true, "trailing_off") => Some(TerminatorChoice::TrailingOff(TrailingOffNode(node))),
            (true, "trailing_off_question") => Some(TerminatorChoice::TrailingOffQuestion(
                TrailingOffQuestionNode(node),
            )),
            _ => None,
        }
    }
}
