impl<'tree> FromNodeKind<'tree> for TranscriptionOptionChoice<'tree> {
    /** Classify a node into this choice's own alternatives.

    Returns `None` for a node of any other kind. That is a refusal,
    not a failure: the caller holds a node this choice does not
    describe, and saying so is the only true answer available.*/
    fn from_node(node: tree_sitter::Node<'tree>) -> Option<Self> {
        match (node.is_named(), node.kind()) {
            (false, "eye_dialect") => {
                Some(TranscriptionOptionChoice::EyeDialect(EyeDialectNode(node)))
            }
            (false, "partial") => Some(TranscriptionOptionChoice::Partial(PartialNode(node))),
            (false, "full") => Some(TranscriptionOptionChoice::Full(FullNode(node))),
            (false, "detailed") => Some(TranscriptionOptionChoice::Detailed(DetailedNode(node))),
            (false, "coarse") => Some(TranscriptionOptionChoice::Coarse(CoarseNode(node))),
            (false, "checked") => Some(TranscriptionOptionChoice::Checked(CheckedNode(node))),
            (false, "anonymized") => {
                Some(TranscriptionOptionChoice::Anonymized(AnonymizedNode(node)))
            }
            (true, "generic_transcription") => Some(
                TranscriptionOptionChoice::GenericTranscription(GenericTranscriptionNode(node)),
            ),
            _ => None,
        }
    }
}
