/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_utf8_header<'tree>(node: Utf8HeaderNode<'tree>) -> Utf8HeaderChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_249);
    {
        let __f0 = {
            let (leading_extras, __placed) = __cur.fixed(Terminal::of(&SHAPE_660), &Cont::NIL);
            let slot = match __placed {
                Some(__placed) => match __placed {
                    TerminalPlaced::Present(node, ()) => NodeSlot::Present(AtUTF8Node(node)),
                    TerminalPlaced::Missing(node, ()) => {
                        NodeSlot::Missing(KindMissing(AtUTF8Node(node)))
                    }
                    TerminalPlaced::Error(node) => NodeSlot::Error(node),
                },
                None => NodeSlot::Absent(NoChild),
            };
            Positioned::new(leading_extras, slot)
        };
        let __f1 = {
            let (leading_extras, __placed) = __cur.fixed(Terminal::of(&SHAPE_5), &Cont::NIL);
            let slot = match __placed {
                Some(__placed) => match __placed {
                    TerminalPlaced::Present(node, ()) => NodeSlot::Present(NewlineNode(node)),
                    TerminalPlaced::Missing(node, ()) => {
                        NodeSlot::Missing(KindMissing(NewlineNode(node)))
                    }
                    TerminalPlaced::Error(node) => NodeSlot::Error(node),
                },
                None => NodeSlot::Absent(NoChild),
            };
            Positioned::new(leading_extras, slot)
        };
        let Leftovers {
            trailing_extras,
            unexpected,
        } = __cur.finish();
        Utf8HeaderChildren {
            child_0: __f0,
            child_1: __f1,
            trailing_extras,
            unexpected,
        }
    }
}
impl<'tree> Extract<'tree> for Utf8HeaderNode<'tree> {
    type Children<K: KindProof> = Utf8HeaderChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<Utf8HeaderChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_utf8_header(Self(__raw)))
    }
    fn extract_broad(self) -> Utf8HeaderChildren<'tree> {
        extract_utf8_header(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<Utf8HeaderChildren<'tree>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
