/// Reconstruct the typed children of this node (spec Section 7).
#[must_use]
pub fn extract_word_prefix<'tree>(node: WordPrefixNode<'tree>) -> WordPrefixChildren<'tree> {
    let __raw = node.0;
    let __children = collect_children(__raw);
    let mut __cur = Cursor::new(&__children, &SHAPES_274);
    let content = {
        let __c0 = __cur.tail(&SHAPES_8);
        let (leading_extras, __placed) = __cur.fixed(
            ChoiceAt {
                shape: &SHAPE_709,
                select: choice_709,
                missing: &TAGS_48,
            },
            &__c0,
        );
        let slot = match __placed {
            Some(__placed) => match __placed {
                ChoicePlaced::Value(__pick) => NodeSlot::Present(match __pick {
                    ChoicePick709::A0(node) => WordPrefixChoice::Variant0(AmpNode(node)),
                    ChoicePick709::A1(node) => WordPrefixChoice::Variant1(AmpTildeNode(node)),
                    ChoicePick709::A2(node) => WordPrefixChoice::Variant2(AmpPlusNode(node)),
                }),
                ChoicePlaced::Missing(node, tag) => NodeSlot::Missing(match tag {
                    KindTag48::AmpPlusNode => {
                        WordPrefixMissing::AmpPlus(KindMissing(AmpPlusNode(node)))
                    }
                    KindTag48::AmpNode => WordPrefixMissing::Amp(KindMissing(AmpNode(node))),
                    KindTag48::AmpTildeNode => {
                        WordPrefixMissing::AmpTilde(KindMissing(AmpTildeNode(node)))
                    }
                }),
                ChoicePlaced::Error(node) => NodeSlot::Error(node),
            },
            None => NodeSlot::Absent(NoChild),
        };
        Positioned::new(leading_extras, slot)
    };
    let Leftovers {
        trailing_extras,
        unexpected,
    } = __cur.finish();
    WordPrefixChildren {
        content,
        trailing_extras,
        unexpected,
    }
}
impl<'tree> Extract<'tree> for WordPrefixNode<'tree> {
    type Children<K: KindProof> = WordPrefixChildren<'tree>;
    fn extract_as<K: KindProof>(
        self,
        evidence: &K::Evidence,
    ) -> Result<WordPrefixChildren<'tree>, K::Refusal> {
        K::admit(evidence, self.0).map(|__raw| extract_word_prefix(Self(__raw)))
    }
    fn extract_broad(self) -> WordPrefixChildren<'tree> {
        extract_word_prefix(self)
    }
    fn extract_admitted(
        self,
        grammar: &CanonicalLanguage,
    ) -> Result<WordPrefixChildren<'tree>, AdmittedRefusal> {
        <Self as Extract<'tree>>::extract_as::<KindAdmitted>(self, grammar)
    }
}
